    greetingsTestHint: 'இது முன்னோட்டம் அல்ல. அந்த நபருக்கு உண்மையான வாழ்த்து இப்போதே சென்றடையும் — செயலியில் அறிவிப்பும், அவரது தொலைபேசியில் புஷ் செய்தியும். இது சோதனை எனக் குறிக்கப்படும்.',
    greetingsTestToMe: 'எனக்கு அனுப்பு',
    greetingsTestDay: 'எந்தச் சிறப்பு நாள்',
    greetingsTestNoDays: 'முதலில் ஒரு சிறப்பு நாளைச் சேர்க்கவும் — சோதிக்க எதுவும் இல்லை.',
    greetingsTestConfirmTitle: '{name} க்கு உண்மையான வாழ்த்தை அனுப்பவா?',
    greetingsTestConfirmBody: 'இது இப்போதே அவர்களின் அறிவிப்புகளிலும், தொலைபேசியில் புஷ் செய்தியாகவும் வந்துசேரும். சோதனை எனக் குறிக்கப்பட்டாலும், பார்ப்பதற்கு மற்ற அட்டைகளைப் போலவே இருக்கும்.',
    greetingsNeverSaved: 'இந்த அமைப்புகள் இதுவரை மாற்றப்படவில்லை.',
    greetingsOverrideHint: '{year} க்கு மட்டும். உங்கள் விடுமுறை நாட்காட்டி இந்தப் பெயரை அறிந்தவுடன், தேதியை மீண்டும் நாட்காட்டியே தீர்மானிக்கும்.',
    greetingsLoadFailed: 'வாழ்த்து அமைப்புகளை ஏற்ற முடியவில்லை. அவை ஏற்றப்படும் வரை இங்கு எதையும் மாற்ற முடியாது — ஆவணத்தைப் படிக்காத திரையிலிருந்து சேமித்தால் அதில் சேமிக்கப்பட்டுள்ள அனைத்தும் அழிந்துவிடும்.',
    greetingsNoOccasions: 'வாழ்த்துகள் இயக்கத்தில் உள்ளன, ஆனால் கீழே உள்ள ஒவ்வொரு சந்தர்ப்பமும் அணைக்கப்பட்டுள்ளது — அடுத்த இயக்கம் எதையும் அனுப்பாது.',
    greetingsDaysDueOnNextRun: '{date} அன்று {n} — இவற்றை நிறுவனம் முழுவதும் பார்க்கும்.',
    greetingsFallbackUnknown: 'சொந்தப் பட்டியல் இல்லை — இங்கு யார் கையொப்பமிடுவது என்பது பெறுநர் இருக்கும் நிறுவனத்தைப் பொறுத்தது.',
    greetingsDropsHolidayLink: 'நிலையான தேதிக்கு மாறினால் இந்த நாளின் விடுமுறை இணைப்பு நீக்கப்படும்.',
