    capApproveLeads: 'தலைவர்களை அனுமதி', capApproveLeadsDesc: 'அனுமதிப்பவர்களாக உள்ள கீழ்நிலை பாத்திரங்களை அனுமதிக்கலாம். அணை \u2192 அனுமதிப்பவர் அல்லாத பணியாளர்களை மட்டும் அனுமதிக்கும்.',
