    capApproveTechnicians: 'தொழில்நுட்பர்களை அனுமதி', capApproveTechniciansDesc: 'தொழில்நுட்ப வகை பணியாளர்களைத் தேர்வு/அனுமதிக்கலாம். அணை \u2192 இந்தப் பாத்திரம் தொழில்நுட்பர்களை உரிமை கோர அல்லது அனுமதிக்க முடியாது.',
    capReports: 'அறிக்கைகள்', capReportsDesc: 'அறிக்கைகளைப் பார்க்கலாம்',
    capManageShifts: 'ஷிஃப்ட்களை நிர்வகி', capManageShiftsDesc: 'குழு உறுப்பினர்களுக்கு இரவுநேர ஷிஃப்ட் காலங்களை ஒதுக்கு',
    capManageLeaves: 'விடுப்புகளை நிர்வகி', capManageLeavesDesc: 'விடுப்பு வகைகள் மற்றும் சிறப்பு விடுப்புகளை நிர்வகி',
    capViewUsers: 'பயனர்களைப் பார்', capViewUsersDesc: 'பயனர்களைப் பார்த்து அவர்களின் சுருக்கம் & தினசரி அறிக்கைகளைப் பதிவிறக்கு — படிக்க மட்டுமே (சேர்க்க/திருத்த முடியாது)',
    capManageUsers: 'பயனர்களை நிர்வகி', capManageUsersDesc: 'பயனர்கள், நிறுவனங்கள் மற்றும் வெளியூர் இடங்களை நிர்வகி',
    capSystemAdmin: 'System Admin', capSystemAdminDesc: 'முழு அணுகல் — தரவுத்தள ஆசிரியர் மற்றும் பாத்திர மேலாண்மை (அனைத்தையும் குறிக்கிறது)',
    catTechnician: 'தொழில்நுட்பர்', catTechnicianDesc: 'மற்றவர்களால் தேர்வு செய்யக்கூடியவர், உணவு கொடுப்பனவுகளுக்கு தகுதியானவர் (எ.கா. தொழில்நுட்பர், குழு தலைவர்).',
    catExecutive: 'நிர்வாகி', catExecutiveDesc: 'அனுமதிகள் பக்கத்தில் அனுமதிக்கப்படுகிறது. உணவு கொடுப்பனவு இல்லை; தேர்வு செய்ய முடியாது.',
